<script lang="ts">
 import {base} from '$app/paths';
 import {present} from '$lib/motion/present';import {MotionPlayer} from '$lib/motion/player';
 import {board,nodeById,pathPoints,polyline,neighbors} from '$lib/game/board';
 import {publicGame,type PublicGame} from '$lib/game/projection';
 import {controlsGuard,availablePatrols,legalGuardSteps,guardCanFinish,noviceOptions,noviceBounds,canUndoFirstTurn} from '$lib/game/engine';
 import {noviceNames,blessingNames,blessingCopy,type RoomState,type Intent,type GuardId,type Guard,type Novice,type Blessing,type PendingRoll} from '$lib/game/model';
 import {initialReview,type ReviewChoice,type Speed} from '$lib/review';
 import WishArtwork from './WishArtwork.svelte';import GuardPortrait from './GuardPortrait.svelte';
 import Abbey from './Abbey.svelte';import AbbessPawn from './AbbessPawn.svelte';import MovementHand from './MovementHand.svelte';import ArtCard from './ArtCard.svelte';import Dice from './Dice.svelte';
 let {game,actor='',publicView=false,incoming=null,motion=new MotionPlayer(),send,rollDie=die,busy=false,error=''}=$props<{game:RoomState|null;actor?:string;publicView?:boolean;incoming?:PublicGame|null;motion?:MotionPlayer;send:(intent:Intent)=>void|Promise<void>;rollDie?:()=>number;busy?:boolean;error?:string}>();
 function die(){const bytes=new Uint32Array(1);do{crypto.getRandomValues(bytes);}while(bytes[0]>=4294967292);return bytes[0]%6+1;}
 const view:PublicGame|null=$derived(game?publicGame(game):incoming);
 const mine:Novice|undefined=$derived(!publicView?game?.novices.find((n:Novice)=>n.uid===actor):undefined);
 const ownerGuards:Guard[]=$derived(game?.guards.filter((g:Guard)=>!publicView&&g.uid===actor)||[]);
 let selectedGuard=$state<GuardId>('abbess'),speed=$state<Speed>('Sneak'),route=$state<number[]>([]),stage=$state<'cards'|'map'>('cards'),draftKey=$state(''),showWish=$state(false),showBlessing=$state<string|null>(null),targeting=$state<string|null>(null),noiseTarget=$state<{guard:GuardId;toward:number}|null>(null),showLog=$state(false);
 const guard:Guard|undefined=$derived(game?.guards.find((g:Guard)=>g.id===selectedGuard));
 const publicGuard:PublicGame['guards'][number]|undefined=$derived(view?.guards.find((g:PublicGame['guards'][number])=>g.id===selectedGuard));
 const canGuard=$derived(!!game&&!!guard&&controlsGuard(game,actor,guard));
 const planning=$derived(!!mine&&view?.phase==='novices'&&!mine.submitted);
 const chooseCards=$derived(planning&&stage==='cards'&&!targeting);
 const ownWish=$derived(mine?board.keys.find(k=>k.id===mine.wish):undefined);
 const cardEntity:Novice|Guard|undefined=$derived(showBlessing?game?.novices.find((n:Novice)=>n.uid===showBlessing)??game?.guards.find((g:Guard)=>g.id===showBlessing):undefined);
 const card:Blessing|undefined=$derived(cardEntity?.blessing);
 const entityName=(id:string)=>id==='abbess'?'Abbess':id==='prioress'?'Prioress':noviceNames[game?.novices.find((n:Novice)=>n.uid===id)?.character??0];
 const fixture=$derived({...initialReview(),guardDot:publicGuard?.dot??26,facing:publicGuard?.facing??'South'});
 const options=$derived(game&&mine&&planning&&stage==='map'&&!targeting?noviceOptions(game,mine,route,speed):[]);
 const legal=$derived(game&&guard&&canGuard&&!targeting?legalGuardSteps(game,guard):[]);
 const bounds=$derived(mine?noviceBounds(mine,speed):{min:0,max:0});
 const steps=$derived(Math.max(0,route.length-1));
 const canCommit=$derived(planning&&steps<=bounds.max&&(steps>=bounds.min||!!mine?.caught&&route.at(-1)===mine.character+1));
 const pending:PendingRoll|null|undefined=$derived(game?.pending);
 const rollerGuard:Guard|undefined=$derived(game?.guards.find((g:Guard)=>g.id===pending?.roller));
 const canResolve=$derived(!!pending&&(rollerGuard?!!game&&controlsGuard(game,actor,rollerGuard):pending.roller===actor));
 $effect(()=>{if(game&&!mine&&!game.guards.some((g:Guard)=>g.id===selectedGuard&&controlsGuard(game,actor,g))){const owned=game.guards.find((g:Guard)=>controlsGuard(game,actor,g));if(owned)selectedGuard=owned.id;}});
 $effect(()=>{
  const key=mine&&view?`${view.epoch}:${view.round}:${view.segment}:${mine.dot}:${mine.submitted}:${mine.log.length}:${view.phase}`:'';
  if(key!==draftKey){draftKey=key;route=mine?[mine.dot]:[];speed=mine?.caught?'Walk':view?.round===1?mine?.firstSpeed??'Sneak':'Sneak';stage=mine?.caught?'map':'cards';targeting=null;noiseTarget=null;}
 });
 function act(intent:Intent){if(busy)return;void send(intent);}
 function boardChoice(choice:ReviewChoice){if(choice.type==='move')act({type:'guard-step',guard:selectedGuard,dot:choice.dot});}
 function playBlessing(){
  if(!card||!showBlessing)return;const entity=showBlessing,kind=card.kind;showBlessing=null;
  if(kind==='false-noise'){targeting=entity;noiseTarget=null;stage='map';return;}
  act({type:'blessing',entity,...(kind==='reroll'?{value:rollDie()}:{})});
 }
 const blessingAllowed=$derived(!!card&&!card.used&&!!view&& (card.kind==='extra-move'?(mine&&showBlessing===mine.uid?planning&&!mine.caught:view.phase==='guards'):card.kind==='false-noise'?view.phase==='guard-hearing':!!pending));
</script>
<svelte:window onkeydown={e=>{if(e.key==='Escape'){showWish=false;showBlessing=null;showLog=false;}}}/>
{#if view}
<div class="game-surface" data-production-component="GameSurface" aria-busy={busy} data-revision={view.revision} use:present={{signature:JSON.stringify(game??view)+speed+route.join(','),player:motion}}>
 <header class="game-status"><strong data-motion-id="game-result" data-motion-state={view.revision+':'+view.phase}>Night {view.round} / 15</strong><span>Captures {view.captures} / {view.target}</span><span>{view.phase==='novices'?'Novices move':view.phase==='patrols'?mine?'Waiting for guards to choose routes':'Choose patrols':view.phase==='guards'?'Guards move':view.phase==='ended'?'Game over':'Listening'}</span><details class="public-info"><summary>Patrols &amp; movement</summary>{#each view.guards as g}<p><GuardPortrait guard={g.id}/><b>{g.id==='abbess'?'Abbess':'Prioress'}</b> · {g.patrol===null?'Choosing route':g.path.join(' → ')}</p>{/each}{#each view.novices as n}<p>{n.name} · {n.speed??'Choosing movement'}</p>{/each}</details><button onclick={()=>showLog=!showLog} aria-expanded={showLog}>Log</button></header>
 {#if chooseCards}
 <section class="movement-stage" aria-label="Choose movement cards"><h1>{noviceNames[mine!.character]} · choose movement</h1><MovementHand extra={mine!.extra} selected={speed} disabled={busy} locked={mine!.caught?'Walk':view.round===1?mine!.firstSpeed??undefined:undefined} onselect={value=>{speed=value;route=[mine!.dot];}}/><p>{view.round===1?'First turn: novices move twice, using the same speed card for both movements.':'Choose your speed, then plan your private route.'}</p><button class="primary" onclick={()=>stage='map'}>Plan route with {speed}</button></section>
 {:else}
 <div class="live-map">
 <Abbey sightGuards={view.guards} {busy} state={fixture} tabletop={publicView} interaction={canGuard&&view.phase==='guards'&&!targeting?'guard':'view'} legalDots={legal} onchoice={boardChoice} canTurn={false} pawnName={selectedGuard==='abbess'?'Abbess':'Prioress'} pawnIndex={selectedGuard==='abbess'?6:7} motionId={'guard:'+selectedGuard} focusDot={targeting?publicGuard?.dot:mine?route.at(-1)??mine.dot:publicGuard?.dot} heading={mine?`${noviceNames[mine.character]} · private map`:selectedGuard==='abbess'?'Abbess':'Prioress'} showFacing={!mine} hint={targeting?'Tap a direction beside either guard.':mine&&view.phase==='patrols'?'Waiting for guards to choose routes':planning?'Tap lit spaces to plan your route.':view.phase==='ended'?'The game is complete.':canGuard&&view.phase==='guards'?'Drag the guard or tap a lit destination.':view.messages.at(-1)}>
 {#snippet boardOverlay()}
 <svg class="game-map-overlay" viewBox="0 0 1000 1038" aria-label="Routes and clues">{#each view.guards as g}{#if g.path.length}<polyline class="public-patrol" class:prioress={g.id==='prioress'} points={polyline(pathPoints(g.path))}><title>{g.id} patrol: {g.path.join(' → ')}</title></polyline>{/if}{/each}{#if mine&&route.length>1&&planning}<polyline class="private-route" points={polyline(pathPoints(route))}/>{/if}</svg>
 {#each view.guards.filter((g:PublicGame['guards'][number])=>g.id!==selectedGuard) as g}{@const p=nodeById.get(g.dot)!}<div class="other-guard" style:left={p.x/10+'%'} style:top={p.y/10.38+'%'} data-motion-id={'guard:'+g.id} data-motion-kind="travel" data-motion-state={g.dot+g.facing}><AbbessPawn facing={g.facing} index={g.id==='abbess'?6:7}/></div>{/each}
 {#each view.novices.filter((n:PublicGame['novices'][number])=>n.dot!==null||n.uid===mine?.uid) as n}{@const id=n.uid===mine?.uid?planning?route.at(-1)??mine!.dot:mine!.dot:n.dot!}{@const p=nodeById.get(id)!}<div class="live-novice" class:caught={n.caught} style:left={p.x/10+'%'} style:top={p.y/10.38+'%'} data-motion-id={'novice:'+n.uid} data-motion-state={id} data-motion-kind="travel" data-motion-enter="true" aria-label={`${n.name}${n.uid===mine?.uid?' private position':' spotted'} at ${id}`}><img src={base+`/art/moonlit/character-${n.character}.webp`} alt={n.name}/><span>{n.caught?'Caught':n.uid===mine?.uid?'You':n.name}</span></div>{/each}
 {#each view.clues as c}{@const a=nodeById.get(c.at)!}{@const b=nodeById.get(c.toward)!}<div class="live-clue" data-kind={c.kind} data-motion-id={'clue:'+c.id} data-motion-state={c.id} data-motion-enter="true" style:left={(a.x+(b.x-a.x)*.45)/10+'%'} style:top={(a.y+(b.y-a.y)*.45)/10.38+'%'} aria-label={`${c.kind==='noise'?'Noise':'Vanished'} at ${c.at} toward ${c.toward}`}><img src={base+`/art/moonlit/${c.kind==='noise'?'noise':'vanished'}.webp`} alt={c.kind}/><span style:transform={`rotate(${Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI}deg)`}>➜</span></div>{/each}
 {/snippet}
 {#snippet boardControls(camera)}
 <div class="live-targets">
 {#each options as id}{@const p=nodeById.get(id)!}<button style:left={camera.x+p.x*camera.scale+'px'} style:top={camera.y+p.y*camera.scale+'px'} aria-label={`Plan step to ${id}`} disabled={busy} onclick={()=>route=[...route,id]}>{id}</button>{/each}
 {#if targeting}{#each view.guards as g}{#each neighbors(g.dot) as id}{@const p=nodeById.get(id)!}<button style:left={camera.x+p.x*camera.scale+'px'} style:top={camera.y+p.y*camera.scale+'px'} aria-pressed={noiseTarget?.guard===g.id&&noiseTarget?.toward===id} aria-label={`Aim noise from ${g.id} toward ${id}`} onclick={()=>noiseTarget={guard:g.id,toward:id}}>{id}</button>{/each}{/each}{/if}
 </div>
 {/snippet}
 </Abbey>
 </div>
 {/if}
 <section class="game-controls" aria-label="Game controls">
 {#if error}<p class="game-error" role="alert">{error}</p>{/if}
 {#if view.phase==='ended'}<h2>{view.winnerTeam==='guards'?'The guards win':view.winners.map(uid=>view.novices.find((n:PublicGame['novices'][number])=>n.uid===uid)?.name).join(' & ')+' won!'}</h2>{#if game?.host===actor}<button onclick={()=>act({type:'rematch',seed:crypto.getRandomValues(new Uint32Array(1))[0]||1})}>Play again</button>{/if}
 {:else if targeting}<p>Choose where the noise points. Your blessing stays private until its reveal.</p><button onclick={()=>{targeting=null;noiseTarget=null;}}>Cancel blessing</button><button disabled={!noiseTarget||busy} onclick={()=>{if(noiseTarget){act({type:'blessing',entity:targeting!,...noiseTarget});targeting=null;noiseTarget=null;}}}>Place noise</button>
 {:else if pending}<div class="pending-roll"><Dice managed value={pending.value} {motion} revision={view.revision}/><p>Noise roll: <b>{pending.value}</b>. Blessings may change this result.</p></div>{#if canResolve}<button disabled={busy} onclick={()=>act({type:'resolve-roll'})}>Resolve hearing</button>{/if}
 {:else if mine&&planning&&!chooseCards}<p class="private-route-log" aria-label="Private route">{route.join(' → ')} · {steps}/{bounds.max} {speed} steps</p><button disabled={route.length<=1||busy} onclick={()=>route=route.slice(0,-1)}>Undo step</button>{#if !mine.caught}<button onclick={()=>stage='cards'}>Change movement</button>{/if}<button disabled={!canCommit||busy} onclick={()=>act({type:'novice-move',route:[...route],speed})}>Commit movement</button>
 {:else if mine&&view.phase==='patrols'}<p role="status">Waiting for guards to choose routes</p>
 {:else if mine&&view.phase==='novice-hearing'&&!mine.rolled}<button disabled={busy} onclick={()=>act({type:'novice-roll',value:rollDie()})}>Roll for noise</button>
 {:else if canGuard&&guard&&(view.phase==='guards'||view.phase==='patrols')}<div class="guard-select" aria-label="Select guard">{#each game!.guards.filter((g:Guard)=>controlsGuard(game!,actor,g)) as g}<button aria-pressed={selectedGuard===g.id} onclick={()=>selectedGuard=g.id}><GuardPortrait guard={g.id}/>{g.id==='abbess'?'Abbess':'Prioress'}{g.finished?' · done':''}</button>{/each}</div>
 {#if availablePatrols(game!,guard).length}<label>Patrol<select aria-label="Choose patrol" disabled={busy} value="" onchange={e=>{if(e.currentTarget.value!=='')act({type:'patrol',guard:selectedGuard,card:Number(e.currentTarget.value)});}}><option value="">Choose a patrol…</option>{#each availablePatrols(game!,guard) as id}<option value={id}>{id>=14?'About Turn':`${board.guardRoutes[id].colour} · ${board.guardRoutes[id].a} ↔ ${board.guardRoutes[id].b}`}</option>{/each}</select></label>{/if}
 {#if view.phase==='guards'}<div class="guard-speed"><button aria-pressed={guard.speed==='Walk'} disabled={guard.steps>0||guard.finished||busy} onclick={()=>act({type:'guard-speed',guard:selectedGuard,speed:'Walk'})}>Walk · {guard.extra?'4–5':'3–4'}</button><button aria-pressed={guard.speed==='Run'} disabled={guard.steps>0||guard.finished||busy} onclick={()=>act({type:'guard-speed',guard:selectedGuard,speed:'Run'})}>Run · {guard.extra?'6–7':'5–6'}</button></div><span>{guard.steps} steps</span><button disabled={!guardCanFinish(guard)||busy} onclick={()=>act({type:'guard-finish',guard:selectedGuard})}><GuardPortrait guard={selectedGuard}/>Finish {selectedGuard==='abbess'?'Abbess':'Prioress'} movement</button>{/if}
 {:else if game&&view.phase==='guard-hearing'}{#each game.guards.filter((g:Guard)=>controlsGuard(game,actor,g)&&!g.rolled) as g}<button disabled={busy} onclick={()=>act({type:'guard-roll',guard:g.id,value:rollDie()})}><GuardPortrait guard={g.id}/>Listen with {g.id==='abbess'?'Abbess':'Prioress'}</button>{/each}{#if game.guards.every((g:Guard)=>g.rolled)&&game.guards.some((g:Guard)=>controlsGuard(game,actor,g))}<button disabled={busy} onclick={()=>act({type:'advance'})}>Next round</button>{/if}
 {:else if !chooseCards}<p role="status">{mine?.submitted?'Movement committed. Waiting for the other players.':view.messages.at(-1)}</p>{/if}
 {#if game&&mine&&canUndoFirstTurn(game,mine)}<button disabled={busy} onclick={()=>act({type:'novice-undo'})}>Undo first turn</button>{/if}
 {#if mine&&ownWish}<div class="private-hand"><button onclick={()=>showWish=true}>Secret wish · {mine.key?'Key ✓':`Key ${ownWish.id} at ${ownWish.node}`} · {mine.item?'Wish ✓':`Wish at ${ownWish.goalnode}`}</button><button onclick={()=>showBlessing=mine.uid}>Blessing: {blessingNames[mine.blessing.kind]}{mine.blessing.used?' · used':''}</button></div>{/if}
 {#each ownerGuards as g}<button onclick={()=>showBlessing=g.id}><GuardPortrait guard={g.id}/>{g.id==='abbess'?'Abbess':'Prioress'} blessing{g.blessing.used?' · used':''}</button>{/each}
 {#each view.novices.filter(n=>n.blessing!==null) as n}<p class="revealed-blessing">{n.name} revealed {blessingNames[n.blessing!]}</p>{/each}
 </section>
 {#if showWish&&mine&&ownWish}<div class="modal-backdrop"><button class="modal-dismiss" aria-label="Dismiss secret wish" onclick={()=>showWish=false}></button><div class="card-modal" role="dialog" aria-modal="true" aria-label="Your secret wish"><button onclick={()=>showWish=false}>Close secret wish</button><ArtCard title={ownWish.text}>{#snippet artwork()}<WishArtwork wish={ownWish.id} title={ownWish.text}/>{/snippet}<div class="wish-details"><span>Key {ownWish.id} · dot {ownWish.node}</span><span>Wish · dot {ownWish.goalnode}</span><span>Home · dot {mine.character+1}</span></div></ArtCard><p>{mine.key?'Key collected.':'Find your key first.'} {mine.item?'Wish collected. Return home.':''}</p></div></div>{/if}
 {#if showBlessing&&card}<div class="modal-backdrop"><button class="modal-dismiss" aria-label="Dismiss blessing" onclick={()=>showBlessing=null}></button><div class="card-modal" role="dialog" aria-modal="true" aria-label="Your blessing"><button onclick={()=>showBlessing=null}>Close blessing</button><ArtCard face="blessing" title={blessingNames[card.kind]}><p class="card-copy">{blessingCopy[card.kind]}</p></ArtCard><button disabled={!blessingAllowed||busy} onclick={playBlessing}>{card.used?'Already used':'Use blessing'}</button></div></div>{/if}

 {#if showLog}<section class="history-panel" aria-label="Game log"><button onclick={()=>showLog=false}>Close log</button>{#each view.messages as message}<p>{message}</p>{/each}{#if mine}<h3>Your private route log</h3>{#each mine.log as entry}<p>Round {entry.round}.{entry.segment} · {entry.speed} · {entry.route.join(' → ')}</p>{/each}{/if}</section>{/if}
</div>
{/if}
<style>
 .game-surface{height:100%;width:100%;min-height:0;display:flex;flex-direction:column;background:#0c202b;color:#f5e4be;font:15px Arial;position:relative}.game-status{display:flex;align-items:center;gap:16px;flex-wrap:wrap;padding:8px 14px;border-bottom:1px solid #a1b09566;flex:none;min-height:48px}.game-status strong{font:20px Georgia}.game-status button{margin-left:auto}.game-surface button,.game-surface select{min-height:44px;border:1px solid #b9c6a788;background:#244250;color:#fff0c7;border-radius:8px;padding:8px 12px;font:14px Arial;cursor:pointer}.game-surface button[aria-pressed=true]{background:#e5cb91;color:#15303c}.game-surface button:disabled{opacity:.45;cursor:default}.game-surface .primary{background:#ead39b;color:#18333f}.movement-stage{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:12px 20px;overflow:hidden}.movement-stage h1{font:24px Georgia;margin:0 0 12px}.movement-stage p{font-size:14px;margin:12px 0}.movement-stage :global(.movement-hand){flex:none}.live-map{flex:1;min-height:0}.game-controls{flex:none;display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:wrap;padding:10px 14px;border-top:1px solid #b0b79566;background:#16303d}.game-controls p{margin:0;line-height:1.5;font-size:14px}.game-controls label{display:flex;gap:6px;align-items:center}.guard-select,.guard-speed,.private-hand{display:flex;gap:6px;flex-wrap:wrap}.private-hand{margin-left:auto}.private-hand button{font-size:12px}.game-map-overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:5}.private-route{stroke:#7ff0dc;stroke-width:7;fill:none;stroke-linecap:round;stroke-linejoin:round}.other-guard{position:absolute;width:64px;height:64px;transform:translate(-50%,-50%);z-index:6;pointer-events:none}.live-novice{position:absolute;width:38px;height:55px;transform:translate(-50%,-70%);z-index:7;pointer-events:none;filter:drop-shadow(0 2px 3px #07141b)}.live-novice img{width:100%;height:44px;object-fit:contain}.live-novice span{position:absolute;top:44px;left:50%;transform:translateX(-50%);padding:2px 5px;background:#193c49;border:1px solid #78eddb;border-radius:4px;color:#ffefc6;white-space:nowrap;font:bold 12px Arial}.live-novice.caught{margin-left:20px}.live-novice.caught span{border-color:#ffaf87;background:#583d35}.live-clue{position:absolute;width:34px;height:34px;transform:translate(-50%,-50%);z-index:7;pointer-events:none}.live-clue img{width:100%;height:100%;object-fit:contain}.live-clue span{position:absolute;right:-14px;top:8px;color:#ffe18b;font:bold 24px Arial;text-shadow:1px 2px #09202b}.live-targets{position:absolute;inset:0;pointer-events:none;z-index:11}.live-targets button{position:absolute;transform:translate(-50%,-50%);width:44px;height:44px;min-height:44px;padding:0;border-radius:50%;border:2px solid #8af5de;background:#173e48e8;color:#fff2c4;font-weight:bold;pointer-events:auto}.live-targets button[aria-pressed=true]{background:#efda9e}.public-patrol{fill:none;stroke:#8cf0db;stroke-width:8;stroke-linecap:round;stroke-linejoin:round;opacity:.65}.public-patrol.prioress{stroke:#fffaf0;stroke-dasharray:10 6;stroke-width:5}.public-info{position:relative;z-index:21;max-width:min(450px,calc(100% - 28px));background:#102935f5;border:1px solid #b9c6a788;border-radius:8px;font:13px/1.5 Arial}.public-info summary{padding:8px;cursor:pointer;min-height:36px}.public-info[open]{position:absolute;top:8px;right:70px;max-height:55%;overflow:auto}.public-info p{padding:6px 12px;margin:0}.wish-details{display:flex;flex-direction:column;justify-content:center;gap:6px;font-size:clamp(10px,6cqw,18px);line-height:1.3;width:100%;text-align:center}.card-modal :global(.painted-title){font-size:clamp(10px,5.5cqw,18px)}.card-modal .card-copy{font-size:clamp(10px,6cqw,18px);line-height:1.3;margin:0;text-align:center}.game-error{width:100%;color:#ffbda3}.modal-backdrop{position:absolute;inset:0;z-index:30;display:grid;place-items:center;background:#0c202bf5;overflow:auto;padding:16px}.game-surface .modal-dismiss{position:absolute;inset:0;width:100%;height:100%;border:0;background:transparent;cursor:default}.card-modal{position:relative;pointer-events:none;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:16px;overflow:auto}.card-modal>*{pointer-events:auto}.card-modal :global(.painted-card){pointer-events:auto;width:240px;min-width:240px;flex-shrink:0}.history-panel{position:absolute;inset:50px 0 0;background:#102b38f5;z-index:30;padding:18px;overflow:auto}.history-panel p{line-height:1.5;padding:6px;border-bottom:1px solid #e1d3a333}.history-panel h3{font:22px Georgia}.pending-roll{display:flex;align-items:center;gap:12px}.pending-roll :global(.noise-die-model){width:64px;height:64px}
 @media(max-width:600px){.game-status{gap:8px;font-size:12px}.game-status strong{font-size:17px}.game-controls{padding:8px;gap:6px}.private-hand{margin:0;justify-content:center;width:100%}.private-hand button{min-height:44px}.movement-stage{padding:10px 14px}.movement-stage h1{font-size:20px}.game-controls label{font-size:12px}.game-controls button,.game-controls select{font-size:12px;padding:7px}.private-route-log{width:100%;text-align:center}.game-status>span:nth-of-type(2){display:none}}
 @media(max-height:500px){.game-status{min-height:40px;padding:4px 12px}.game-status button{min-height:34px;padding:4px 10px}.movement-stage{padding:4px 18px}.movement-stage h1{font-size:19px;margin-bottom:2px}.movement-stage p{margin:2px}.movement-stage :global(.movement-hand){padding:4px 0;max-width:540px}.movement-stage .primary{min-height:36px;padding:5px 12px}.card-modal{flex-direction:row}.card-modal>*{pointer-events:auto}.card-modal :global(.painted-card){pointer-events:auto;width:170px;min-width:170px}.game-controls{padding:5px 10px;gap:6px}.private-hand{width:auto;margin-left:auto}.private-hand button{max-width:200px}.game-controls p{font-size:12px}}
